class Solution928 {
    List<Integer> [] g;
    boolean[] isVisit;
    int[] quickFind;
    public int minMalwareSpread(int[][] graph, int[] initials) {
        // 建图
        g = new List[graph.length];
        Arrays.setAll(g, e -> new ArrayList<>());
        for (int i = 0; i < graph.length - 1; i++) {
            for (int j = i + 1; j < graph.length; j++) {
                if (graph[i][j] == 1) {
                    g[i].add(j);
                    g[j].add(i);
                }
            }
        }
        quickFind = new int[graph.length];
        for (int i : initials) {
            quickFind[i]++;
        }
        // 如果一片区域只有一个节点那么去掉这个节点 感染数量减少的个数就是这片区域的个数
        // 如果一片区域至少有两个感染的节点
        isVisit = new boolean[graph.length];
        int[] res = new int[] {Integer.MAX_VALUE, 1};
        for (int initial : initials) {
            int[] initRes = new int[]{initial, 1};
            for (int branch : g[initial]) {
                // 如果一个branch里面能dfs到病毒 那么整个branch都要淘汰
                int[] branchRes = dfs(branch, initial, initial);
                if (branchRes[1] == 0) {
                    // 分支没有病毒 计入分支结果
                    initRes[1] += branchRes[0];
                }
            }
            // 赋值结果res
            if (res[1] < initRes[1]) {
                res[0] = initRes[0];
                res[1] = initRes[1];
            } else if (res[1] == initRes[1]){
                res[0] = Math.min(res[0], initRes[0]);
            }
        }
        return res[0];
    }

    private int[] dfs(int son, int fa, int initial) {
        if (quickFind[son] == 0 && !isVisit[son]) {
            isVisit[son] = true;
            int[] ret = new int[]{1,0};
            for (int node : g[son]) {
                if (node != fa) {
                    if (!isVisit[node]) {
                        int[] dfsRes = dfs(node, son, initial);
                        ret[0] += dfsRes[0];
                        ret[1] += dfsRes[1];
                    }
                }
            }
            return ret;
        } else {
            if (son == initial) {
                return new int[] {0, 0};
            }
            // 如果遍历到了病毒节点 需要标记这个分支为病毒分支不能计入总数
            return new int[]{0, 1};
        }
    }
}
